// 1. Get Webhook Data
const webhookData = $node["Webhook"].getMatchingItem().json.body;

// 2. Get Settings
const settingsRows = $node["Get Settings"].getMatchingItem();
const settingsAll = $items("Get Settings");
const storeSettings = {};
settingsAll.forEach(s => {
  storeSettings[s.json.Label] = s.json.Value;
});

// 3. Get Discounts
const discountsAll = $items("Get Discounts");

// 4. Re-calculate Totals
let subtotal = 0;
webhookData.items.forEach(item => {
  const addonsPrice = (item.addons || []).reduce((sum, a) => sum + (Number(a.price) || 0), 0);
  subtotal += (Number(item.price) + addonsPrice) * Number(item.qty);
});

// 5. Validate Discount
let discountAmount = 0;
let discountCode = (webhookData.discountCode || "").trim().toUpperCase();
if (discountCode) {
  const match = discountsAll.find(d => (d.json.Code || "").trim().toUpperCase() === discountCode);
  if (match && match.json.Active === 'Y') {
    const d = match.json;
    const type = (d.Type || "").toLowerCase();
    const val = Number(d.Value || 0);
    const minOrder = Number(d['Min Order'] || 0);
    const maxD = Number(d['Max Discount'] || 99999);

    if (subtotal >= minOrder) {
      discountAmount = type === 'percent' ? Math.round(subtotal * val / 100) : val;
      discountAmount = Math.min(discountAmount, maxD, subtotal);
    }
  }
}

// 6. Fee & Total
const deliveryFee = (webhookData.deliveryType === 'delivery') ? Number(storeSettings['Delivery Fee'] || 0) : 0;
const total = subtotal - discountAmount + deliveryFee;

// 7. Gen ID
const now = new Date();
const dateStr = (now.getMonth() + 1).toString().padStart(2, '0') + now.getDate().toString().padStart(2, '0');
const random = Math.floor(1000 + Math.random() * 9000);
const orderId = "ORD-" + dateStr + "-" + random;

// 8. Build WhatsApp link
const storePhone = storeSettings['Store Phone'] || "919876543210";
let itemText = webhookData.items.map(i => "• " + i.name + " x " + i.qty).join("%0A");
const waText = "🍽 *New Order: " + orderId + "*%0A%0A" +
    "*Customer:* " + webhookData.customer.name + "%0A" +
    "*Phone:* " + webhookData.customer.phone + "%0A" +
    "*Type:* " + webhookData.deliveryType.toUpperCase() + "%0A%0A" +
    "*Items:*%0A" + itemText + "%0A%0A" +
    "*Subtotal:* Rs." + subtotal + "%0A" +
    (discountAmount > 0 ? "*Discount:* -Rs." + discountAmount + "%0A" : "") +
    (deliveryFee > 0 ? "*Delivery:* Rs." + deliveryFee + "%0A" : "") +
    "*Total:* *Rs." + total + "*%0A%0A" +
    (webhookData.deliveryType === 'delivery' ? "*Address:* " + webhookData.address : "") +
    (webhookData.notes ? "%0A*Notes:* " + webhookData.notes : "");

const waLink = "https://wa.me/" + storePhone + "?text=" + waText;

return {
  json: {
    "Order ID": orderId,
    "Timestamp": now.toLocaleString(),
    "Customer Name": webhookData.customer.name,
    "Phone": webhookData.customer.phone,
    "Items": JSON.stringify(webhookData.items),
    "Subtotal": subtotal,
    "Discount Code": discountCode,
    "Discount Amount": discountAmount,
    "Delivery Fee": deliveryFee,
    "Total": total,
    "Payment Method": webhookData.paymentMethod,
    "Payment Status": "Pending",
    "Order Status": "New",
    "Delivery Type": webhookData.deliveryType,
    "Address": webhookData.address || "N/A",
    "Notes": webhookData.notes || "",
    "Razorpay Link": "",
    "WhatsApp Sent": "N",
    "waLink": waLink,
    "upiQrUrl": storeSettings['UPI QR Image URL'] || ""
  }
};
